import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { ufiSummaryTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIText from "UIText.react";
import UIPressable from "UIPressable.react";
import { UIRow } from "UIStack.react";
import UFIReactionIcons from "UFIReactionIcons.react";
import { compactCount } from "UICount";

const styles = stylex.create({
  row: { paddingInline: 16, paddingBlock: 10, gap: ufiSummaryTokens.gap },
  counts: { marginInlineStart: "auto", gap: 12 },
});

export default function UFISummary({ feedback, onCommentsPress }) {
  const data = useFragment(
    graphql`
      fragment UFISummary_feedback on Feedback {
        i18n_reaction_count
        reaction_count {
          count
        }
        top_reactions(first: 3) {
          edges {
            reaction_count
            node {
              id
              localized_name
            }
          }
        }
        reactors(first: 3) {
          count_reduced
          edges {
            node {
              id
              name
            }
          }
        }
        comment_count {
          total_count
        }
        share_count {
          count
        }
        video_view_count_text
      }
    `,
    feedback,
  );
  const reactionCount = data.reaction_count?.count ?? 0;
  const comments = data.comment_count?.total_count ?? 0;
  const shares = data.share_count?.count ?? 0;
  if (!reactionCount && !comments && !shares) {
    return null;
  }
  const types = (data.top_reactions?.edges ?? []).map((edge) => edge.node.id);
  const firstReactor = data.reactors?.edges?.[0]?.node?.name;
  return (
    <UIRow xstyle={styles.row}>
      {reactionCount > 0 ? (
        <UIPressable label={`${data.i18n_reaction_count} reactions`} showOverlay={false}>
          <UIRow gap={6}>
            <UFIReactionIcons types={types} />
            <UIText type="meta" color="secondary">
              {firstReactor && reactionCount > 1 ? fbt(fbt.param("name", firstReactor) + " and " + fbt.param("count", compactCount(reactionCount - 1)) + " others", "reactors summary") : data.i18n_reaction_count}
            </UIText>
          </UIRow>
        </UIPressable>
      ) : null}
      <UIRow xstyle={styles.counts}>
        {comments > 0 ? (
          <UIPressable label="Comments" onPress={onCommentsPress} showOverlay={false}>
            <UIText type="meta" color="secondary">
              {fbt(fbt.plural("comment", comments, { many: "comments", showCount: "yes", value: compactCount(comments) }), "comment count in a story footer")}
            </UIText>
          </UIPressable>
        ) : null}
        {shares > 0 ? (
          <UIText type="meta" color="secondary">
            {fbt(fbt.plural("share", shares, { many: "shares", showCount: "yes", value: compactCount(shares) }), "share count in a story footer")}
          </UIText>
        ) : null}
        {data.video_view_count_text ? (
          <UIText type="meta" color="secondary">
            {data.video_view_count_text}
          </UIText>
        ) : null}
      </UIRow>
    </UIRow>
  );
}
