// The overlapping reaction glyphs in a story's summary. The glyphs are our
// own: coloured discs with a letter-free symbol per reaction.
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import UIIcon from "UIIcon.react";

const REACTIONS = {
  LIKE: { icon: "like", style: "like" },
  LOVE: { icon: "heart", style: "love" },
  CARE: { icon: "heart", style: "care" },
  HAHA: { icon: "smile", style: "haha" },
  WOW: { icon: "star", style: "wow" },
  SAD: { icon: "smile", style: "sad" },
  ANGRY: { icon: "flag", style: "angry" },
};

const styles = stylex.create({
  row: { display: "inline-flex", alignItems: "center" },
  disc: { display: "inline-flex", alignItems: "center", justifyContent: "center", width: 18, height: 18, borderRadius: "50%", border: `2px solid ${colors.cardBackground}`, marginInlineStart: -4 },
  first: { marginInlineStart: 0 },
  like: { backgroundColor: colors.reactionLike },
  love: { backgroundColor: colors.reactionLove },
  care: { backgroundColor: colors.reactionCare },
  haha: { backgroundColor: colors.reactionHaha },
  wow: { backgroundColor: colors.reactionWow },
  sad: { backgroundColor: colors.reactionSad },
  angry: { backgroundColor: colors.reactionAngry },
});

export function ReactionGlyph({ type, first = false, size = 10 }) {
  const reaction = REACTIONS[type] ?? REACTIONS.LIKE;
  return (
    <span {...stylex.props(styles.disc, styles[reaction.style], first && styles.first)} aria-hidden="true">
      <UIIcon name={reaction.icon} size={size} color="onAccent" filled />
    </span>
  );
}

export default function UFIReactionIcons({ types }) {
  return (
    <span {...stylex.props(styles.row)}>
      {types.map((type, i) => (
        <ReactionGlyph key={type} type={type} first={i === 0} />
      ))}
    </span>
  );
}

export const REACTION_TYPES = Object.keys(REACTIONS);
