// Renders text with its entity ranges as links: mentions, hashtags and
// URLs. Offsets are UTF-16 indices, like the server's.
import { graphql, useFragment } from "react-relay";
import UILink from "UILink.react";

function hrefOf(entity) {
  return entity?.url ?? null;
}

export function renderRanges(text, ranges, truncateAt = null) {
  const limit = truncateAt ?? text.length;
  const parts = [];
  let cursor = 0;
  const sorted = [...(ranges ?? [])].filter((range) => range.entity != null).sort((a, b) => a.offset - b.offset);
  for (const range of sorted) {
    if (range.offset >= limit) {
      break;
    }
    if (range.offset > cursor) {
      parts.push(text.slice(cursor, range.offset));
    }
    const end = Math.min(range.offset + range.length, limit);
    parts.push(
      <UILink key={`${range.offset}:${range.length}`} href={hrefOf(range.entity)} color="link" strong={range.entity.__typename !== "ExternalUrl"}>
        {text.slice(range.offset, end)}
      </UILink>,
    );
    cursor = end;
  }
  if (cursor < limit) {
    parts.push(text.slice(cursor, limit));
  }
  return parts;
}

export default function TextWithEntities({ text: textRef, truncateAt = null }) {
  const data = useFragment(
    graphql`
      fragment TextWithEntities_text on TextWithEntities {
        text
        ranges {
          offset
          length
          entity {
            __typename
            ... on User {
              id
              url
            }
            ... on Page {
              id
              url
            }
            ... on Group {
              id
              url
            }
            ... on Hashtag {
              id
              url
            }
            ... on ExternalUrl {
              id
              url
            }
          }
        }
      }
    `,
    textRef,
  );
  if (!data?.text) {
    return null;
  }
  return <>{renderRanges(data.text, data.ranges, truncateAt)}</>;
}
