// Compact counts ("1.2K", "3M"), as the UI shows reactions and followers.
const compact = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const full = new Intl.NumberFormat("en-US");

export function compactCount(count) {
  return count < 1000 ? String(count) : compact.format(count);
}

export function fullCount(count) {
  return full.format(count);
}
