import { graphql, useFragment } from "react-relay";
import UIText from "UIText.react";
import UILink from "UILink.react";
import UIIcon from "UIIcon.react";
import VerifiedBadge from "VerifiedBadge.react";

export default function StoryTitle({ section }) {
  const data = useFragment(
    graphql`
      fragment StoryTitle_section on StoryTitleSection {
        is_group_post
        story {
          actors {
            __typename
            id
            name
            url
            ... on User {
              is_verified
            }
            ... on Page {
              is_verified
            }
          }
          to {
            id
            name
            url
          }
          memory {
            years_ago
            title
          }
        }
      }
    `,
    section,
  );
  const story = data.story;
  const actor = story?.actors?.[0];
  if (!actor) {
    return null;
  }
  return (
    <UIText as="h3" type="body" weight="semibold" numberOfLines={2}>
      {data.is_group_post && story.to ? (
        <>
          <UILink href={story.to.url} strong>
            {story.to.name}
          </UILink>
          <UIIcon name="caretRight" size={12} />
        </>
      ) : null}
      <UILink href={actor.url} strong>
        {actor.name}
      </UILink>
      {actor.is_verified ? <VerifiedBadge /> : null}
      {story.memory ? (
        <UIText type="body" color="secondary">
          {" "}
          {story.memory.title}
        </UIText>
      ) : null}
    </UIText>
  );
}
