// The "..." menu on a story. Its items come with the story; opening it is
// a popover with a menu.
import { useRef, useState, useCallback } from "react";
import { graphql, useFragment } from "react-relay";
import UIIconButton from "UIIconButton.react";
import UIPopover from "UIPopover.react";
import UIMenu, { UIMenuItem } from "UIMenu.react";

export default function StoryOverflowMenu({ menu }) {
  const data = useFragment(
    graphql`
      fragment StoryOverflowMenu_menu on StoryOverflowMenu {
        items {
          key
          label
          description
          icon_name
        }
      }
    `,
    menu,
  );
  const anchor = useRef(null);
  const [open, setOpen] = useState(false);
  const close = useCallback(() => setOpen(false), []);
  return (
    <span ref={anchor}>
      <UIIconButton icon="more" label="Actions for this post" filled={false} onPress={() => setOpen((value) => !value)} testid="story-overflow" />
      {open ? (
        <UIPopover anchorRef={anchor} onClose={close} label="Post actions" width={340}>
          <UIMenu label="Post actions">
            {data.items.map((item) => (
              <UIMenuItem key={item.key} label={item.label} description={item.description} icon={item.icon_name} onPress={close} />
            ))}
          </UIMenu>
        </UIPopover>
      ) : null}
    </span>
  );
}
