import { graphql, useFragment } from "react-relay";
import UIAvatar from "UIAvatar.react";
import UILink from "UILink.react";
import ProfileHovercardTrigger from "ProfileHovercardTrigger.react";

export default function StoryActorPhoto({ section }) {
  const data = useFragment(
    graphql`
      fragment StoryActorPhoto_section on StoryActorPhotoSection {
        has_story_ring
        story {
          actors {
            id
            name
            url
            profile_picture(size: 40) {
              uri
            }
          }
        }
      }
    `,
    section,
  );
  const actor = data.story?.actors?.[0];
  if (!actor) {
    return null;
  }
  return (
    <ProfileHovercardTrigger actorId={actor.id}>
      <UILink href={actor.url} label={actor.name}>
        <UIAvatar src={actor.profile_picture?.uri} size={40} ring={data.has_story_ring} />
      </UILink>
    </ProfileHovercardTrigger>
  );
}
