// Loads the component a @match field's server-chosen renderer names, for
// MatchContainer: synchronously when its module is defined, otherwise by
// suspending until its package file is loaded.
import JSResource from "JSResource";

export default function loadModuleComponent(reference) {
  const resource = JSResource(reference);
  const module = resource.getModuleIfRequired();
  if (module === null) {
    throw resource.load();
  }
  return module.default ?? module;
}
