// A story's attachments. The server picks a renderer for each one (a @match
// field); the renderer's module is loaded on first use, and its data is
// normalized with the module's own normalization artifact.
import { graphql, useFragment } from "react-relay";
import MatchContainer from "react-relay/lib/relay-hooks/MatchContainer";
import loadModuleComponent from "RelayModuleComponent";
import UIErrorBoundary from "UIErrorBoundary.react";
import LoggingSurface from "LoggingSurface.react";

export default function StoryAttachments({ content, mode = "feed" }) {
  const data = useFragment(
    graphql`
      fragment StoryAttachments_content on StoryContentSection {
        attachment_container {
          story {
            attachments {
              deduplication_key
              style_list
              styles {
                ...PhotoAttachment_renderer @module(name: "PhotoAttachment.react")
                ...AlbumAttachment_renderer @module(name: "AlbumAttachment.react")
                ...VideoAttachment_renderer @module(name: "VideoAttachment.react")
                ...ReelAttachment_renderer @module(name: "ReelAttachment.react")
                ...ShareAttachment_renderer @module(name: "ShareAttachment.react")
                ...SharedStoryAttachment_renderer @module(name: "SharedStoryAttachment.react")
              }
            }
          }
        }
      }
    `,
    content,
  );
  const attachments = data.attachment_container?.story?.attachments ?? [];
  if (!attachments.length) {
    return null;
  }
  return (
    <LoggingSurface name="attachment" as="div">
      {attachments.map((attachment) => (
        <UIErrorBoundary key={attachment.deduplication_key} name="attachment">
          <MatchContainer match={attachment.styles} props={{ mode }} loader={loadModuleComponent} />
        </UIErrorBoundary>
      ))}
    </LoggingSurface>
  );
}
