// The row of reactions that opens over the Like button after a hover
// delay. The delay is a deferred call: in benchmark mode the step flushes it
// instead of waiting.
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import { reactionDockTokens } from "ComponentTokens.stylex";
import UIPressable from "UIPressable.react";
import { ReactionGlyph, REACTION_TYPES } from "UFIReactionIcons.react";

const styles = stylex.create({
  dock: { position: "absolute", bottom: "calc(100% + 4px)", left: 8, zIndex: 20, display: "flex", gap: 4, padding: 6, borderRadius: radii.pill, backgroundColor: colors.popoverBackground, boxShadow: elevation.e3 },
  item: { borderRadius: "50%", padding: 2, transform: { default: "none", ":hover": "scale(1.2)" }, transitionDuration: reactionDockTokens.transitionDuration },
});

export default function UFIReactionsDock({ onPick }) {
  return (
    <div role="toolbar" aria-label="Reactions" data-testid="reactions-dock" {...stylex.props(styles.dock)}>
      {REACTION_TYPES.map((type) => (
        <UIPressable key={type} label={type.toLowerCase()} onPress={() => onPick(type)} showOverlay={false} xstyle={styles.item}>
          <ReactionGlyph type={type} first size={18} />
        </UIPressable>
      ))}
    </div>
  );
}
