// Wraps a name or avatar; hovering it opens the person's hovercard after
// the hover-intent delay, a deferred call in benchmark mode. The card's
// module is loaded when it's first needed.
import { Suspense, useCallback, useId, useRef, useState } from "react";
import * as stylex from "@stylexjs/stylex";
import { deferUntilFlush, cancelDeferred } from "TimerGuard";
import JSResource from "JSResource";
import UILayer from "UILayer.react";

const styles = stylex.create({ wrapper: { display: "inline-flex", flexShrink: 0 } });
const Hovercard = JSResource("ProfileHovercard.react");

function LazyHovercard(props) {
  const module = Hovercard.getModuleIfRequired();
  if (module === null) {
    throw Hovercard.load();
  }
  const Component = module.default;
  return <Component {...props} />;
}

export default function ProfileHovercardTrigger({ actorId, children }) {
  const [rect, setRect] = useState(null);
  const ref = useRef(null);
  const key = `hovercard:${useId()}`;
  const onPointerEnter = useCallback(() => deferUntilFlush(key, () => setRect(ref.current?.getBoundingClientRect() ?? null)), [key]);
  const onPointerLeave = useCallback(() => {
    cancelDeferred(key);
    setRect(null);
  }, [key]);
  return (
    <span ref={ref} onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} {...stylex.props(styles.wrapper)}>
      {children}
      {rect !== null && actorId ? (
        <UILayer>
          <Suspense fallback={null}>
            <LazyHovercard actorId={actorId} rect={rect} />
          </Suspense>
        </UILayer>
      ) : null}
    </span>
  );
}
