// The story's text. Long texts are cut at the server's truncation offset
// with a "See more" button that expands them in place.
import { useState } from "react";
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors, type } from "BaseTokens.stylex";
import { storyMessageTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIText from "UIText.react";
import UIPressable from "UIPressable.react";
import TextWithEntities from "TextWithEntities.react";

const styles = stylex.create({
  message: { paddingInline: 16, paddingTop: 4, paddingBottom: 12, whiteSpace: "pre-wrap" },
  textOnly: { fontSize: type.bodyLargeSize, lineHeight: type.bodyLargeLineHeight },
  background: { minHeight: 240, display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center", fontSize: type.headline2Size, fontWeight: type.weightBold, color: "white", backgroundImage: `linear-gradient(135deg, ${colors.accent60}, ${colors.info60})` },
  seeMore: { display: "inline", fontWeight: type.weightSemibold, color: storyMessageTokens.text },
});

export default function StoryMessage({ content }) {
  const data = useFragment(
    graphql`
      fragment StoryMessage_content on StoryContentSection {
        message_container {
          is_text_only
          background_style
          story {
            message_truncation_offset
            message {
              text
              ...TextWithEntities_text
            }
          }
        }
      }
    `,
    content,
  );
  const [expanded, setExpanded] = useState(false);
  const container = data.message_container;
  const story = container?.story;
  if (!story?.message?.text) {
    return null;
  }
  const truncateAt = expanded ? null : story.message_truncation_offset;
  const textOnly = container.is_text_only && story.message.text.length < 140;
  return (
    <div data-ad-preview="message" {...stylex.props(styles.message, textOnly && styles.textOnly, textOnly && container.background_style && styles.background)}>
      <UIText type={textOnly ? "bodyLarge" : "body"} color={textOnly && container.background_style ? "onAccent" : "primary"}>
        <TextWithEntities text={story.message} truncateAt={truncateAt} />
        {truncateAt !== null ? (
          <>
            {"... "}
            <UIPressable as="span" role="button" label="See more" onPress={() => setExpanded(true)} showOverlay={false} xstyle={styles.seeMore} testid="see-more">
              {fbt("See more", "Expands a truncated post text")}
            </UIPressable>
          </>
        ) : null}
      </UIText>
    </div>
  );
}
