import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import UIButton from "UIButton.react";
import UIText from "UIText.react";
import { UIRow, UIColumn } from "UIStack.react";

const styles = stylex.create({
  bar: { paddingBlock: 10, paddingInline: 16, backgroundColor: colors.cardBackgroundFlat, borderBottom: `1px solid ${colors.divider}` },
});

export default function StoryCallToAction({ story }) {
  const data = useFragment(
    graphql`
      fragment StoryCallToAction_story on Story {
        sponsored_data {
          cta_label
          cta_type
          advertiser {
            name
          }
        }
        attachments {
          title
          source {
            text
          }
        }
      }
    `,
    story,
  );
  const sponsored = data.sponsored_data;
  if (!sponsored?.cta_label) {
    return null;
  }
  const attachment = data.attachments?.[0];
  return (
    <UIRow gap={12} justify="between" xstyle={styles.bar}>
      <UIColumn grow>
        <UIText type="meta" color="secondary" numberOfLines={1}>
          {attachment?.source?.text}
        </UIText>
        <UIText weight="semibold" numberOfLines={1}>
          {attachment?.title}
        </UIText>
      </UIColumn>
      <UIButton label={sponsored.cta_label} use="secondary" testid="cta" />
    </UIRow>
  );
}
