import * as stylex from "@stylexjs/stylex";
import { spacing } from "BaseTokens.stylex";
import UIPressable from "UIPressable.react";
import UIIcon from "UIIcon.react";
import UIText from "UIText.react";
import { UIColumn } from "UIStack.react";

const styles = stylex.create({
  menu: { padding: spacing.s4 },
  item: { gap: spacing.s6, paddingBlock: spacing.s4, paddingInline: spacing.s4, borderRadius: 6 },
  iconWell: { display: "flex", alignItems: "center", justifyContent: "center", width: 36, height: 36, borderRadius: "50%", backgroundColor: "rgba(0,0,0,0.05)", flexShrink: 0 },
});

export function UIMenuItem({ label, description, icon, selected = false, onPress, testid }) {
  return (
    <UIPressable role="menuitem" label={label} onPress={onPress} block testid={testid} aria-checked={selected || undefined} xstyle={styles.item}>
      {icon ? (
        <span {...stylex.props(styles.iconWell)}>
          <UIIcon name={icon} size={20} color="primary" />
        </span>
      ) : null}
      <UIColumn grow>
        <UIText weight="semibold">{label}</UIText>
        {description ? <UIText type="meta" color="secondary">{description}</UIText> : null}
      </UIColumn>
      {selected ? <UIIcon name="check" color="accent" /> : null}
    </UIPressable>
  );
}

export default function UIMenu({ label, children }) {
  return (
    <div role="menu" aria-label={label} {...stylex.props(styles.menu)}>
      {children}
    </div>
  );
}
