import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import UIText from "UIText.react";
import UILink from "UILink.react";
import UIIcon from "UIIcon.react";
import UITooltip from "UITooltip.react";
import { shortRelativeTime, fullDate } from "CurrentTime";

const styles = stylex.create({ row: { display: "flex", alignItems: "center", gap: 4 } });

function StoryTimestamp({ story }) {
  return (
    <UITooltip text={fullDate(story.creation_time)}>
      <UILink href={story.url} label={fullDate(story.creation_time)}>
        <UIText type="meta" color="secondary">
          {shortRelativeTime(story.creation_time)}
        </UIText>
      </UILink>
    </UITooltip>
  );
}

function PrivacyIcon({ scope }) {
  if (!scope) {
    return null;
  }
  return <UIIcon name={scope.icon_name} size={12} label={scope.label} />;
}

export default function StoryMetadata({ sections }) {
  const data = useFragment(
    graphql`
      fragment StoryMetadata_sections on StoryMetadataSection @relay(plural: true) {
        key
        label
        story {
          creation_time
          url
          privacy_scope {
            icon_name
            label
          }
          sponsored_data {
            label
          }
        }
      }
    `,
    sections,
  );
  return (
    <div {...stylex.props(styles.row)}>
      {data.map((section, i) => (
        <span key={section.key} {...stylex.props(styles.row)}>
          {i > 0 ? <UIText type="meta" color="secondary" aria-hidden="true">·</UIText> : null}
          {section.key === "timestamp" ? <StoryTimestamp story={section.story} /> : null}
          {section.key === "privacy" ? <PrivacyIcon scope={section.story.privacy_scope} /> : null}
          {section.key === "sponsored" ? <UIText type="meta" color="secondary">{section.story.sponsored_data?.label}</UIText> : null}
          {section.key === "label" ? <UIText type="meta" color="secondary">{section.label}</UIText> : null}
        </span>
      ))}
    </div>
  );
}
