// A tooltip shown on hover after a delay. In benchmark mode the delay is a
// deferred call the step can flush; tooltips aren't part of the journey.
import { useCallback, useRef, useState } from "react";
import * as stylex from "@stylexjs/stylex";
import { radii, type } from "BaseTokens.stylex";
import { deferUntilFlush, cancelDeferred } from "TimerGuard";
import UILayer from "UILayer.react";

const styles = stylex.create({
  wrapper: { display: "inline-flex" },
  tip: { position: "fixed", zIndex: 60, paddingBlock: 6, paddingInline: 10, borderRadius: radii.md, backgroundColor: "rgba(20,22,26,0.88)", color: "white", fontSize: type.metaSize, pointerEvents: "none", maxWidth: 280 },
});

let nextKey = 1;

export default function UITooltip({ text, children }) {
  const [rect, setRect] = useState(null);
  const ref = useRef(null);
  const key = useRef(`tooltip-${nextKey++}`);
  const show = useCallback(() => {
    deferUntilFlush(key.current, () => setRect(ref.current?.getBoundingClientRect() ?? null));
  }, []);
  const hide = useCallback(() => {
    cancelDeferred(key.current);
    setRect(null);
  }, []);
  return (
    <span ref={ref} onPointerEnter={show} onPointerLeave={hide} {...stylex.props(styles.wrapper)}>
      {children}
      {rect !== null ? (
        <UILayer>
          <span role="tooltip" style={{ top: rect.bottom + 4, left: rect.left }} {...stylex.props(styles.tip)}>
            {text}
          </span>
        </UILayer>
      ) : null}
    </span>
  );
}
