import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { storyHeaderTokens } from "ComponentTokens.stylex";
import { UIRow, UIColumn } from "UIStack.react";
import StoryActorPhoto from "StoryActorPhoto.react";
import StoryTitle from "StoryTitle.react";
import StoryMetadata from "StoryMetadata.react";
import StoryOverflowMenu from "StoryOverflowMenu.react";
import LoggingSurface from "LoggingSurface.react";

const styles = stylex.create({
  header: { paddingTop: 12, paddingInline: 16, paddingBottom: 0, gap: storyHeaderTokens.gap },
});

export default function StoryHeader({ contextLayout }) {
  const data = useFragment(
    graphql`
      fragment StoryHeader_contextLayout on StoryContextLayout {
        actor_photo {
          ...StoryActorPhoto_section
        }
        title {
          ...StoryTitle_section
        }
        metadata {
          ...StoryMetadata_sections
        }
        overflow_menu {
          ...StoryOverflowMenu_menu
        }
      }
    `,
    contextLayout,
  );
  return (
    <LoggingSurface name="header">
      <UIRow gap={8} align="start" xstyle={styles.header}>
        {data.actor_photo ? <StoryActorPhoto section={data.actor_photo} /> : null}
        <UIColumn grow gap={2}>
          {data.title ? <StoryTitle section={data.title} /> : null}
          {data.metadata ? <StoryMetadata sections={data.metadata} /> : null}
        </UIColumn>
        {data.overflow_menu ? <StoryOverflowMenu menu={data.overflow_menu} /> : null}
      </UIRow>
    </LoggingSurface>
  );
}
